window.ATLAS.addDetails("society.nodes",{"nodes":{
"diversification":{"description":{"zh":"把钱分到几只资产上能不能降低波动，看的不是只数，而是它们是否一起涨跌：同涨同跌的十只约等于一只，各走各路的才能互相抵消；而整个市场一起动的那部分系统风险，怎么分散也去不掉。","en":"Whether spreading money across assets lowers the wobble depends not on how many there are but on whether they rise and fall together: ten that move as one behave like one, only independent movers cancel out; and the systematic risk of the whole market moving together cannot be diversified away."},"formula":"σₚ = σ·√((1+ρ)/2)","source":"../investment/basics/diversification/#step1","lessons":[{"slug":"diversification","step":1,"category":"investment","stage":"junior","primary":true}],"aliases":{"zh":["分散投资","不要把鸡蛋放在一个篮子里","投资组合","资产相关性","系统性风险","非系统性风险","买多少只股票才算分散","分散投资为什么降低风险","分散风险","投资组合理论"],"en":["diversification","don’t put all your eggs in one basket","portfolio","asset correlation","systematic risk","idiosyncratic risk","how many stocks to diversify","why diversify investments","diversify","portfolio theory"]}},
"risk-return":{"description":{"zh":"结果越不确定的投资，必须承诺更高的平均回报才有人愿意拿，多出来的那部分叫风险溢价；但承诺的只是平均——平均 5% 的投资，照样会有亏钱的年份，看分布比看平均数更诚实。","en":"An investment with more uncertain results must promise a higher average return before anyone will hold it, and the extra is the risk premium; but only the average is promised — an investment averaging 5% still has losing years, and the distribution tells the truth better than the average."},"source":"../investment/basics/risk-return/#step3","lessons":[{"slug":"risk-return","step":3,"category":"investment","stage":"junior","primary":true}],"aliases":{"zh":["风险和收益","风险溢价","高风险高回报","波动率","为什么风险大回报高","年化收益","平均收益不等于每年收益"],"en":["risk and return","risk premium","high risk high return","volatility","why riskier investments pay more","annual return","average return is not every year’s return"]}},
"stocks-bonds":{"description":{"zh":"买股票是买下公司的一小份所有权，回报来自分红和价格上涨，也会跟着公司缩水；买债券是把钱借给它，按约定收利息、到期拿回本金；公司出事时先还债主，股东排在最后。","en":"Buying a stock buys a small slice of ownership in a company, paid back through dividends and rising prices, and shrinking when the company does; buying a bond lends the company money for agreed interest and the principal back at maturity; if the company fails, lenders are repaid before shareholders."},"source":"../investment/basics/stocks-bonds/#step5","lessons":[{"slug":"stocks-bonds","step":5,"category":"investment","stage":"junior","primary":true}],"aliases":{"zh":["股票","债券","股票和债券的区别","股东","分红","票息","公司破产谁先拿钱","股价是谁定的"],"en":["stocks","bonds","difference between stocks and bonds","shareholder","dividends","coupon","who gets paid first in bankruptcy","who sets the stock price"]}},
"auctions":{"description":{"zh":"第一价格拍卖要压价，第二价格拍卖里说真话是占优策略；英式与第二价格等价、荷式与第一价格等价，平均收益相等；真值不确定时出现赢家的诅咒。单件物品、对称风险中性竞标者的模型。","en":"First-price auctions call for shading, truth-telling is dominant in second-price auctions, English matches second price and Dutch matches first price, and average revenue is equal; with an uncertain true value the winner’s curse appears. A single-item model with symmetric risk-neutral bidders."},"formula":"E[revenue] = 100·(n−1)/(n+1)","source":"../math/applied/auction-basics/#step2","lessons":[{"slug":"auction-basics","step":2,"category":"math","stage":"senior","primary":true}],"note":"No economics group in the atlas; group left OTHER. Edge endpoints are site pages (mechanism-auction, game-theory) merged separately, plus montecarlo which exists in the atlas.","aliases":{"zh":["第二价格拍卖","维克里拍卖"],"en":["second price auction","vickrey auction"]}},
"ethical-frameworks":{"description":{"zh":"同一个决定换一套框架就会问不同的问题：结果主义问总后果好不好，权利框架问有没有越过不可侵犯的边界，公平框架问代价是否落在某一群人身上，同意则问当事人是否知情、能否拒绝——把这些问题分开写，取舍才看得清。","en":"Under different frameworks the same decision raises different questions: consequentialism asks whether the overall outcome is good, a rights framework whether an inviolable line is crossed, a fairness framework whether the costs fall on one group, and consent whether those affected are informed and free to refuse — writing these out separately makes the trade-offs visible."},"source":"../psychology/ethics/ethics-decisions/#step0","lessons":[{"slug":"ethics-decisions","step":0,"category":"psychology","stage":"senior","primary":true}],"aliases":{"zh":["伦理学","道德决策","功利主义","义务论","结果主义","知情同意","电车难题","怎么做伦理判断"],"en":["ethics","moral decision making","utilitarianism","deontology","consequentialism","informed consent","trolley problem","how to make an ethical judgment"]}},
"fees-compounding":{"description":{"zh":"基金或账户的年费按资产比例收，等于把每年的收益率从 r 降成 r − f；这个差距随复利指数式拉大：年收益 5% 放 30 年，1% 的年费会吃掉约四分之一的终值。","en":"An annual fee charged as a share of assets lowers each year’s return from r to r − f, and compounding widens the gap exponentially: at 5% a year for 30 years, a 1% annual fee eats about a quarter of the final value."},"formula":"A = P(1 + r − f)ᵗ","source":"../investment/rates/fees-compounding/#step1","lessons":[{"slug":"fees-compounding","step":1,"category":"investment","stage":"senior","primary":true}],"aliases":{"zh":["管理费","基金费率","1% 的费率影响有多大","指数基金低费率","费用侵蚀收益","复利的代价","为什么推荐指数基金","指数基金"],"en":["management fee","fund expense ratio","how much does a 1% fee cost","low-cost index funds","fee drag on returns","cost of compounding fees","index fund","index funds"]}},
"interest-rates-bonds":{"description":{"zh":"债券的价格是它未来每一笔票息和本金按当前利率折现后的总和；利率上升，折现变重，旧债券的固定票息就不如新债券，只能降价到买家同样能拿到新利率为止；期限越长，跌得越多。","en":"A bond’s price is the sum of its future coupons and principal, each discounted at today’s interest rate; when rates rise, discounting gets heavier and an old bond’s fixed coupon falls behind new bonds, so its price must drop until a buyer earns the new rate too; the longer the maturity, the bigger the drop."},"formula":"P = Σ C/(1+r)ᵗ + F/(1+r)ᵀ","source":"../investment/rates/interest-rates-bonds/#step3","lessons":[{"slug":"interest-rates-bonds","step":3,"category":"investment","stage":"senior","primary":true}],"aliases":{"zh":["债券价格","利率上升债券下跌","为什么加息债券会跌","到期收益率","现值 折现","久期","长期债券利率风险","债券收益率","收益率"],"en":["bond price","rates up bonds down","why do bond prices fall when rates rise","yield to maturity","present value and discounting","duration","interest rate risk of long bonds","bond yield","yield"]}},
"money-as-iou":{"description":{"zh":"物物交换要两个愿望同时对上；一张所有人都信得过的欠条把一笔交易拆成两半。","en":"Barter needs two wants to match at once; an IOU that everyone trusts splits a trade into two halves."},"source":"../economics/money/where-money-comes-from/#ch1","lessons":[{"slug":"where-money-comes-from","step":null,"anchor":"ch1","category":"economics","stage":"senior","primary":true}],"aliases":{"zh":["钱到底是什么","需求的双重巧合","物物交换","为什么需要货币","货币的本质","欠条","钱是怎么来的","钱从哪里来"],"en":["what is money","double coincidence of wants","barter","why do we need money","money is debt","IOU","where does money come from"]}},
"phonemes":{"description":{"zh":"两个词只差一个音、意思就不同（如 pat 和 bat），这组词叫最小对立，那个能区分意义的音就是一个音位；音位之间往往只差一个发音特征，比如声带振不振动（清 / 浊）。","en":"When two words differ in a single sound and mean different things (pat and bat), they form a minimal pair, and the meaning-changing sound is a phoneme; phonemes often differ by just one articulatory feature, such as whether the vocal folds vibrate (voiceless vs voiced)."},"source":"../language/phonology/phonemes/#step1","lessons":[{"slug":"phonemes","step":1,"category":"language","stage":"senior","primary":true}],"aliases":{"zh":["音位","最小对立对","清音 浊音","语音学","音系学","音节结构","复数 s 为什么有时读 z","国际音标"],"en":["phoneme","minimal pair","voiceless and voiced sounds","phonetics","phonology","syllable structure","why is plural s sometimes pronounced z","IPA"]}},
"veil-of-ignorance":{"description":{"zh":"如果在不知道自己会是谁时挑选社会规则，海萨尼说应选平均福祉最高的社会（每个位置机会均等），罗尔斯说这种一次性、改不了的选择应先保证最差的位置（最大最小原则）；风险态度越保守，选择就越从前者滑向后者。","en":"Choosing society’s rules without knowing who you will be, Harsanyi says pick the society with the highest average welfare (each position equally likely), while Rawls says such a one-shot, irreversible choice should first secure the worst position (maximin); the more risk-averse the chooser, the more the choice slides from the first towards the second."},"source":"../psychology/ethics/veil-of-ignorance/#step0","lessons":[{"slug":"veil-of-ignorance","step":0,"category":"psychology","stage":"senior","primary":true}],"aliases":{"zh":["无知之幕","罗尔斯","正义论","最大最小原则","原初状态","差别原则","海萨尼","什么是公平的社会"],"en":["veil of ignorance","John Rawls","A Theory of Justice","maximin principle","original position","difference principle","Harsanyi average utilitarianism","what is a fair society"]}},
"voting-rules-disagree":{"description":{"zh":"相对多数、两轮决选、即时决选、波达计数和孔多塞两两对决，对同一批选票可以选出不同的赢家。","en":"Plurality, two-round runoff, instant runoff, Borda count and the pairwise Condorcet winner can pick different winners from the same ballots."},"source":"../society/civics/same-votes-different-winner/#ch1","lessons":[{"slug":"same-votes-different-winner","step":null,"anchor":"ch1","category":"society","stage":"senior","primary":true}],"aliases":{"zh":["计票方法","选举规则","排序复选制","即时决选","两轮投票","波达计数","为什么换个算法赢家就变了","相对多数制","投票结果不一样","为什么投票结果不一样","投票方法","选举制度","选举","排序投票","选举制度怎么运作"],"en":["voting methods","ranked choice voting","instant runoff","two-round system","Borda count","plurality voting","first past the post","why different voting systems give different winners","how do elections work","election","elections","voting systems"]}},
"vowel-formants":{"description":{"zh":"元音的音高由基频 F0 定，是哪个元音则由声道放大的几个频率峰（共振峰）定：只用前两个 F1、F2，就能把元音画成平面上的点；男人、女人、孩子的点整体错开，要先按说话人整体缩放才能认对。","en":"A vowel’s pitch is set by the fundamental F0, but which vowel it is depends on the frequency peaks the vocal tract amplifies (formants): the first two, F1 and F2, place each vowel as a point on a plane; men’s, women’s and children’s points are shifted as a whole, so they must be rescaled by speaker before vowels can be recognised."},"source":"../language/phonology/vowel-space/#step1","lessons":[{"slug":"vowel-space","step":1,"category":"language","stage":"senior","primary":true}],"aliases":{"zh":["共振峰","元音图","F1 F2","元音四边形","基频和音高","说话人归一化","为什么男女声说同一个元音频率不同"],"en":["formant","vowel chart","first and second formants","vowel quadrilateral","fundamental frequency and pitch","speaker normalization","why do men and women’s vowels differ in frequency"]}},
"loans-create-deposits":{"description":{"zh":"银行放贷时同时写下一笔贷款和一笔新存款，还款时这笔存款消失。","en":"A bank loan writes a loan and a new deposit at the same moment; repaying it deletes the deposit."},"source":"../economics/money/where-money-comes-from/#ch2","lessons":[{"slug":"where-money-comes-from","step":null,"anchor":"ch2","category":"economics","stage":"senior","primary":true}],"aliases":{"zh":["钱是怎么创造出来的","银行怎么造钱","货币乘数","存款准备金率","降准","央行放水","量化宽松","资产负债表","M2","银行是怎么创造货币的","货币创造","货币供应","部分准备金"],"en":["how is money created","how banks create money","money multiplier","reserve requirement","quantitative easing","bank balance sheet","broad money","money creation","money supply","fractional reserve banking"]}},
"spoiler-effect":{"description":{"zh":"一个赢不了的候选人加入，就能把胜利从一个人手里交到另一个人手里。","en":"A candidate who cannot win can still hand victory from one rival to another."},"source":"../society/civics/same-votes-different-winner/#ch2","lessons":[{"slug":"same-votes-different-winner","step":null,"anchor":"ch2","category":"society","stage":"senior","primary":true}],"aliases":{"zh":["搅局者","分票","浪费选票","无关选项独立","中间被挤压","第三方候选人"],"en":["spoiler","vote splitting","wasted vote","IIA","center squeeze","third party candidate"]}},
"bank-run":{"description":{"zh":"银行没亏钱，只要足够多的人同时来取也会倒；存款保险和最后贷款人拆掉了这个临界点。","en":"A solvent bank can still fail if enough people withdraw at once; deposit insurance and a lender of last resort remove the tipping point."},"source":"../economics/money/where-money-comes-from/#ch3","lessons":[{"slug":"where-money-comes-from","step":null,"anchor":"ch3","category":"economics","stage":"senior","primary":true}],"aliases":{"zh":["挤兑","银行会倒闭吗","存款保险","50万","硅谷银行","流动性","最后贷款人","Diamond-Dybvig"],"en":["bank run","can my bank fail","deposit insurance","FDIC","Silicon Valley Bank","liquidity versus solvency","lender of last resort","Diamond-Dybvig"]}},
"duverger-tendency":{"description":{"zh":"只看第一名的单议席选举里，选民会把三方竞争收缩成两方；这是倾向，不是定律。","en":"Under single-seat plurality voting, voters shrink a three-way race to two; a tendency, not a law."},"source":"../society/civics/same-votes-different-winner/#ch2","lessons":[{"slug":"same-votes-different-winner","step":null,"anchor":"ch2","category":"society","stage":"senior","primary":true}],"aliases":{"zh":["迪韦尔热定律","两党制为什么出现","策略性投票","两党制"],"en":["Duverger's law","why two parties","two-party system","strategic desertion"]}},
"median-voter":{"description":{"zh":"选民排在一条线上时，靠近中位选民的候选人一对一谁也赢不了；议题多于一个时这一点消失。","en":"On one line, the candidate nearest the median voter beats any rival head to head; with two issues that resting point disappears."},"source":"../society/civics/same-votes-different-winner/#ch3","lessons":[{"slug":"same-votes-different-winner","step":null,"anchor":"ch3","category":"society","stage":"senior","primary":true}],"aliases":{"zh":["中位选民","向中间靠拢","霍特林模型","候选人为什么趋同","麦凯尔维混沌定理"],"en":["median voter","Hotelling's law","candidates converge to the center","McKelvey chaos theorem","spatial voting"]}},
"quantity-theory-inflation":{"description":{"zh":"长期看，钱和转手速度加起来比东西长得快，物价就涨；短期里多出来的钱先变成产出，供给冲击也能单独推高物价。","en":"In the long run prices rise when money and its velocity outgrow output; in the short run extra money first raises output, and supply shocks can raise prices on their own."},"source":"../economics/money/where-money-comes-from/#ch4","lessons":[{"slug":"where-money-comes-from","step":null,"anchor":"ch4","category":"economics","stage":"senior","primary":true}],"aliases":{"zh":["为什么东西越来越贵","通货膨胀的原因","印钱会导致通胀吗","货币数量论","MV=PY","货币流通速度","滞胀","货币中性","通货膨胀","印钱为什么会涨价"],"en":["why do prices rise","what causes inflation","does printing money cause inflation","quantity theory of money","MV=PY","velocity of money","stagflation","money neutrality","inflation"]}},
"condorcet-paradox":{"description":{"zh":"每个人的排序都一致，多数人的偏好却可以 A 胜 B、B 胜 C、C 又胜 A。","en":"Each voter is consistent, yet the majority can prefer A to B, B to C and C to A."},"source":"../society/civics/same-votes-different-winner/#ch4","lessons":[{"slug":"same-votes-different-winner","step":null,"anchor":"ch4","category":"society","stage":"senior","primary":true}],"aliases":{"zh":["投票悖论","多数循环","石头剪刀布式的多数","孔多塞赢家","表决顺序决定结果","孔多塞悖论","多数人偏好绕圈"],"en":["voting paradox","majority cycle","Condorcet winner","intransitive majority","agenda setting","Condorcet paradox"]}},
"inflation-winners-losers":{"description":{"zh":"意外的通胀把财富从储户搬到固定利率的借款人；预料之中的通胀已经写进了利率，不搬运财富。","en":"Surprise inflation moves wealth from savers to fixed-rate borrowers; inflation everyone expected is already in the interest rate and moves nothing."},"source":"../economics/money/where-money-comes-from/#ch5","lessons":[{"slug":"where-money-comes-from","step":null,"anchor":"ch5","category":"economics","stage":"senior","primary":true}],"aliases":{"zh":["通胀对谁有利","通胀对存款的影响","实际利率","费雪方程","工资跟不上物价","购买力下降"],"en":["who benefits from inflation","inflation and savings","real interest rate","Fisher equation","wages lag prices","purchasing power"]}},
"interest-price-of-time":{"description":{"zh":"名义利率约等于时间的价格加上预期通胀；按利率把未来的钱折回今天，就是现值。","en":"A nominal rate is roughly the price of time plus expected inflation; discounting future money at that rate gives its present value."},"source":"../economics/money/where-money-comes-from/#ch6","lessons":[{"slug":"where-money-comes-from","step":null,"anchor":"ch6","category":"economics","stage":"senior","primary":true}],"aliases":{"zh":["利息是什么","为什么要付利息","现值","名义利率和实际利率","利率上升债券为什么跌"],"en":["what is interest","why pay interest","present value","nominal versus real rate","why bond prices fall when rates rise"]}},
"strategic-voting":{"description":{"zh":"三个以上候选人时，每种非独裁的规则都存在说假话更划算的局面。","en":"With three or more candidates, every non-dictatorial rule has situations where a dishonest ballot pays."},"source":"../society/civics/same-votes-different-winner/#ch5","lessons":[{"slug":"same-votes-different-winner","step":null,"anchor":"ch5","category":"society","stage":"senior","primary":true}],"aliases":{"zh":["策略投票","投给能赢的人","背弃最爱","操纵投票","吉巴德定理"],"en":["tactical voting","favorite betrayal","lesser evil voting","manipulation","Gibbard-Satterthwaite"]}},
"arrow-impossibility":{"description":{"zh":"没有哪种只看排序的规则能同时满足几条合理要求；每种规则都在某一条上让步。","en":"No rule that uses only rankings meets every reasonable condition at once; each gives way somewhere."},"source":"../society/civics/same-votes-different-winner/#ch6","lessons":[{"slug":"same-votes-different-winner","step":null,"anchor":"ch6","category":"society","stage":"senior","primary":true}],"aliases":{"zh":["阿罗定理","不可能定理","有没有公平的投票制度","梅定理","认可投票","评分投票","有没有公平的投票方法","公平的投票方法"],"en":["Arrow's theorem","impossibility theorem","is there a fair voting system","May's theorem","approval voting","score voting"]}},
"loan-amortisation":{"description":{"zh":"每月先付剩余本金的利息，剩下才减本金，所以前几年主要在付利息；多还的钱全部减本金。","en":"Each payment first covers interest on what is still owed and only the rest repays principal, so early payments are mostly interest; extra payments go straight to principal."},"source":"../economics/money/where-money-comes-from/#ch7","lessons":[{"slug":"where-money-comes-from","step":null,"anchor":"ch7","category":"economics","stage":"senior","primary":true}],"aliases":{"zh":["房贷怎么算","等额本息","月供","为什么前几年都在还利息","提前还款","还款计划表","提前还贷划算吗","提前还贷","房贷月供","房贷月供怎么算"],"en":["how is a mortgage calculated","amortization schedule","monthly payment","why early payments are mostly interest","overpaying a mortgage","prepayment","mortgage","how does a mortgage work","mortgage payment"]}},
"apportionment-alabama-paradox":{"description":{"zh":"1880 年按最大余数法，众议院从 299 席加到 300 席，阿拉巴马反而少了一席。","en":"In 1880, under largest remainders, growing the House from 299 to 300 seats took a seat away from Alabama."},"source":"../society/civics/same-votes-different-winner/#ch7","lessons":[{"slug":"same-votes-different-winner","step":null,"anchor":"ch7","category":"society","stage":"senior","primary":true}],"aliases":{"zh":["阿拉巴马悖论","最大余数法","汉密尔顿法","亨廷顿希尔法","议席怎么按人口分","巴林斯基杨定理"],"en":["Alabama paradox","largest remainder method","Hamilton method","Huntington-Hill","apportionment","Balinski-Young theorem"]}},
"monetary-transmission":{"description":{"zh":"央行利率经过市场利率、贷款利率和家庭预算，一到两三年后才落到物价上；浮动利率越多，传得越快越强。","en":"A central bank rate passes through market rates, loan rates and household budgets and reaches prices only after one to three years; more variable-rate debt makes it faster and stronger."},"source":"../economics/money/where-money-comes-from/#ch8","lessons":[{"slug":"where-money-comes-from","step":null,"anchor":"ch8","category":"economics","stage":"senior","primary":true}],"aliases":{"zh":["加息有什么用","央行加息对房贷的影响","货币政策传导","固定利率还是浮动利率","政策时滞","加息多久见效","央行加息有什么用","中央银行","央行","政策利率","加息"],"en":["what does a rate hike do","how rate rises affect mortgages","monetary policy transmission","fixed versus variable rate","long and variable lags","how long until rate rises work","interest rate hike","how do interest rates affect inflation","central bank","policy rate","why do central banks raise rates"]}},
"gerrymandering":{"description":{"zh":"同样的选民，只改选区边界，席位就能从 1 席变到 6 席。","en":"Same voters, redrawn lines: seats can swing from 1 to 6."},"source":"../society/civics/same-votes-different-winner/#ch8","lessons":[{"slug":"same-votes-different-winner","step":null,"anchor":"ch8","category":"society","stage":"senior","primary":true}],"aliases":{"zh":["杰利蝾螈","选区划分不公","塞和拆","效率差距","浪费的选票","选区划分"],"en":["gerrymander","packing and cracking","efficiency gap","wasted votes","redistricting"]}},
"purchasing-power-parity":{"description":{"zh":"长期看通胀高的货币会贬值；短期里资金流动让汇率偏离平价，偏离减半要好几年。","en":"Over the long run a high-inflation currency depreciates; in the short run capital flows push the rate away from parity, and the gap takes years to halve."},"source":"../economics/money/where-money-comes-from/#ch9","lessons":[{"slug":"where-money-comes-from","step":null,"anchor":"ch9","category":"economics","stage":"senior","primary":true}],"aliases":{"zh":["汇率是怎么决定的","巨无霸指数","购买力平价","为什么同样的东西各国价格不同","货币贬值","汇率高估","汇率"],"en":["how are exchange rates set","Big Mac index","purchasing power parity","why prices differ between countries","currency depreciation","overvalued currency","exchange rate"]}},
"condorcet-jury-theorem":{"description":{"zh":"每人略好于抛硬币且独立判断时，多数越大越可靠；略差于硬币或互相跟风时，结论反过来。","en":"If each voter is a little better than a coin and judges alone, bigger majorities are more reliable; if slightly worse or copying, it turns around."},"source":"../society/civics/same-votes-different-winner/#ch9","lessons":[{"slug":"same-votes-different-winner","step":null,"anchor":"ch9","category":"society","stage":"senior","primary":true}],"aliases":{"zh":["群体智慧","群众的智慧","陪审团定理","跟风","从众","多数是不是更可能对"],"en":["wisdom of crowds","jury theorem","herding","correlated votes","is the majority more likely right"]}},
"reading-fairness-claims":{"description":{"zh":"公平是一份清单：守住了哪几条，放弃了哪几条，放弃的那条会不会在你关心的情形里出事。","en":"Fairness is a checklist: which conditions a rule keeps, which it gives up, and whether that matters in your case."},"source":"../society/civics/same-votes-different-winner/#ch10","lessons":[{"slug":"same-votes-different-winner","step":null,"anchor":"ch10","category":"society","stage":"senior","primary":true}],"aliases":{"zh":["什么是公平的选举","选举制度比较","哪种投票制度最好"],"en":["fair election","comparing electoral systems","best voting system"]}},
"game-theory":{"description":{"zh":"把一次互动写成一张表：每格是双方同时出的招、各自的得分。先找占优策略——不管对手出什么都最划算的那招；再找纳什均衡——谁单独换招都不会更好。拍卖、公地、囚徒困境都是同一张表的不同填法。","en":"Write one interaction as a table: each cell holds both sides' simultaneous moves and their scores. First find dominant strategies — moves that pay best no matter what the rival does; then Nash equilibria — where neither side improves by switching alone. Auctions, the commons and the prisoner's dilemma are the same table filled in differently."},"source":"../math/applied/game-theory/#step0","lessons":[{"slug":"game-theory","step":0,"category":"math","stage":"university","primary":true}]},
"mechanism-auction":{"description":{"zh":"机制是给博弈定规则：同一群人、同一件物品，换一条成交规则，报价与结果全变。第一价收最高报价，第二价收第二高报价——后者让说真话不再吃亏。","en":"A mechanism sets the rules for a game: same people, same item, a different settlement rule, and bids and outcome all change. First-price takes the top bid, second-price takes the runner-up — and the latter makes truth-telling cost nothing."},"source":"../math/applied/mechanism-design/#s1","lessons":[{"slug":"mechanism-design","step":null,"category":"math","stage":"university","primary":true}]},
"opportunity-cost":{"description":{"zh":"资源有限而愿望没完，所以必须选；一件事的真实成本，是为它放弃的最好的另一件事。模型：一天十六个清醒的小时，在学习和打工之间分配。","en":"Resources are limited and wants are endless, so you have to choose; the real cost of anything is the best other thing you gave up. Model: splitting sixteen waking hours between study and paid work."},"source":"../demos/scarcity-moves/#c1","lessons":[{"slug":"scarcity-moves","step":null,"anchor":"c1","category":"demos","stage":"university","primary":true}],"aliases":{"zh":["机会成本","稀缺","稀缺性","稀缺性是什么","为什么必须做选择","生产可能性边界","时间的成本","选择的代价"],"en":["opportunity cost","scarcity","what is scarcity","production possibility frontier","the cost of a choice","trade-off"]}},
"supply-demand":{"description":{"zh":"买方愿买量随价跌而增、卖方愿卖量随价涨而增，两条曲线交点就是均衡价格：两边都愿意交易的量。价格变化是沿曲线移动，偏好、收入、技术变了才是整条曲线移动。","en":"Buyers want more as price falls, sellers want more as price rises, and where the two curves cross is the equilibrium price — the quantity both sides plan to trade. A price change moves along a curve; changed tastes, incomes or technology shift the whole curve."},"formula":"Qd = Qs","source":"../math/applied/supply-demand/#step0","lessons":[{"slug":"supply-demand","step":0,"category":"math","stage":"university","primary":true}],"aliases":{"zh":["价格","价格是怎么决定的","供求关系"],"en":["how are prices set","supply and demand"]}},
"marginal-thinking":{"description":{"zh":"好的决定只问“再多一点值不值”：价格取决于最后那一杯水值多少，所以水比钻石便宜；学得越多，下一小时的收获越小，这是收益递减。","en":"A good decision asks only whether one more step is worth it: price depends on what the last cup of water is worth, which is why water is cheaper than diamonds; each extra hour of study gains less, which is diminishing returns."},"source":"../demos/scarcity-moves/#c2","lessons":[{"slug":"scarcity-moves","step":null,"anchor":"c2","category":"demos","stage":"university","primary":true}],"aliases":{"zh":["边际","边际思维","边际成本","边际收益","收益递减","边际效用递减","钻石与水悖论","为什么水比钻石便宜"],"en":["marginal thinking","the margin","marginal cost","marginal benefit","diminishing returns","diminishing marginal utility","diamond water paradox","why is water cheaper than diamonds"]}},
"sunk-cost":{"description":{"zh":"已经花掉、无论如何回不来的钱和时间不该进入决定；唯一该问的是接下来的时间用来干什么最好。难看的电影要不要看完、读了两年不喜欢的专业，是同一道题。","en":"Money and time already spent and gone whatever you do should not enter the decision; the only question is how best to use what comes next. Sitting through a dreadful film and staying in a degree you dislike are the same problem."},"source":"../demos/scarcity-moves/#c2","lessons":[{"slug":"scarcity-moves","step":null,"anchor":"c2","category":"demos","stage":"university","primary":true}],"aliases":{"zh":["沉没成本","沉没成本谬误","已经花了钱要不要继续","电影难看要不要看完","及时止损"],"en":["sunk cost","sunk cost fallacy","should I keep going because I already paid","cut your losses"]}},
"comparative-advantage":{"description":{"zh":"自愿的交换让双方都变好；分工的依据不是谁更强，是谁放弃得更少。模型：小组作业里两个人分配写题和做 PPT。","en":"Voluntary trade makes both sides better off; the basis for specialising is not who is stronger but who gives up less. Model: two students splitting problem-writing and slide-making in a group project."},"source":"../demos/scarcity-moves/#c3","lessons":[{"slug":"scarcity-moves","step":null,"anchor":"c3","category":"demos","stage":"university","primary":true}],"aliases":{"zh":["比较优势","绝对优势","分工","为什么国家之间要贸易","为什么要贸易","自由贸易","交换为什么能双赢","专业化"],"en":["comparative advantage","absolute advantage","division of labour","why do countries trade","why trade","gains from trade","specialisation","specialization"]}},
"price-signal":{"description":{"zh":"价格告诉所有人一个东西现在有多缺，让互不相识的人协调行动。模型：八十个买家、八十个卖家，价格自己找到位置。","en":"A price tells everyone how scarce something is right now and lets strangers coordinate. Model: eighty buyers, eighty sellers and a price that finds its own level."},"source":"../demos/scarcity-moves/#c4","lessons":[{"slug":"scarcity-moves","step":null,"anchor":"c4","category":"demos","stage":"university","primary":true}],"aliases":{"zh":["价格信号","看不见的手","市场怎么协调","价格机制","霜冻为什么让咖啡变贵"],"en":["price signal","invisible hand","price mechanism","how markets coordinate","why a frost makes coffee dearer"]}},
"incentives":{"description":{"zh":"规则奖励什么，你就会得到更多的什么，包括你没想要的那部分。案例：悬赏眼镜蛇、被考核的指标，以及“然后呢”。","en":"Whatever the rules reward, you get more of, including the parts you did not want. Cases: a bounty on cobras, metrics that become targets, and asking “and then what?”."},"source":"../demos/scarcity-moves/#c5","lessons":[{"slug":"scarcity-moves","step":null,"anchor":"c5","category":"demos","stage":"university","primary":true}],"aliases":{"zh":["激励","人会对激励做出反应","眼镜蛇效应","适得其反的政策","为什么好政策会失败","意外后果"],"en":["incentives","people respond to incentives","cobra effect","perverse incentive","unintended consequences","why good policies backfire"]}},
"market-failure":{"description":{"zh":"一个人的选择把成本甩给别人时，价格就会说谎：外部性、公共品、信息不对称。模型：一片公共的湖，船越多，长期总收获反而越少。","en":"When one person's choice pushes costs onto others, prices lie: externalities, public goods, asymmetric information. Model: a shared lake where more boats eventually mean a smaller total catch."},"source":"../demos/scarcity-moves/#c6","lessons":[{"slug":"scarcity-moves","step":null,"anchor":"c6","category":"demos","stage":"university","primary":true}],"aliases":{"zh":["市场失灵","公共品","信息不对称","柠檬市场","过度捕捞","为什么需要政府管"],"en":["market failure","public goods","asymmetric information","market for lemons","overfishing","why markets fail"]}},
"growth-from-ideas":{"description":{"zh":"长期看，生活水平几乎只取决于生产率，生产率来自可以被所有人同时使用的思想。模型：1% 和 4% 的增长率复利七十年，一个翻一番，一个十五倍多。","en":"In the long run, living standards depend almost entirely on productivity, and productivity comes from ideas that everyone can use at once. Model: 1% versus 4% growth compounded over seventy years, doubling versus more than fifteenfold."},"source":"../demos/scarcity-moves/#c7","lessons":[{"slug":"scarcity-moves","step":null,"anchor":"c7","category":"demos","stage":"university","primary":true}],"aliases":{"zh":["经济增长","生产率","内生增长","为什么有的国家富有的国家穷","增长率复利","技术进步"],"en":["economic growth","productivity","endogenous growth","why are some countries rich","compound growth","technological progress"]}},
"spending-is-income":{"description":{"zh":"对一个人成立的事，对所有人一起未必成立：所有人同时省钱，商店卖不出东西、工厂裁员、收入下降，谁也没多存下来。这是节俭悖论，也是衰退自我强化的原因。","en":"What holds for one person does not necessarily hold for everyone: if everyone saves at once, shops sell nothing, factories lay off workers and incomes fall, so nobody saves more. This is the paradox of thrift and why recessions feed on themselves."},"source":"../demos/scarcity-moves/#c8","lessons":[{"slug":"scarcity-moves","step":null,"anchor":"c8","category":"demos","stage":"university","primary":true}],"aliases":{"zh":["节俭悖论","经济衰退","衰退","总需求","为什么会经济危机","合成谬误","大家都不花钱会怎样"],"en":["paradox of thrift","recession","aggregate demand","why do recessions happen","what if everyone stops spending"]}},
"income-to-the-scarce":{"description":{"zh":"谁稀缺、谁难以替代，谁就有议价权，分配是对稀缺的定价；还有一股力量让财富自己集中。模型：一百六十个起点相同的人做公平的抛硬币交易，再打开再分配。","en":"Whatever is scarce and hard to replace has bargaining power; distribution is the pricing of scarcity, and one more force pulls wealth together. Model: 160 people with equal starts trading on fair coin tosses, then redistribution switched on."},"source":"../demos/scarcity-moves/#c9","lessons":[{"slug":"scarcity-moves","step":null,"anchor":"c9","category":"demos","stage":"university","primary":true}],"aliases":{"zh":["收入分配","为什么工资不一样","贫富差距","财富集中","议价权","地租","再分配"],"en":["income distribution","why are wages different","inequality","wealth concentration","bargaining power","land rent","redistribution"]}},
"institutions-trust":{"description":{"zh":"市场长在产权、契约和信任上面；它们降低交易成本，分工才能铺开到陌生人之间。同样的人和资源，制度不同，几十年后就是富国和穷国的差别。","en":"Markets grow on property rights, contracts and trust; these lower transaction costs so that specialisation can reach strangers. The same people and resources under different institutions end up decades later as rich or poor countries."},"source":"../demos/scarcity-moves/#c10","lessons":[{"slug":"scarcity-moves","step":null,"anchor":"c10","category":"demos","stage":"university","primary":true}],"aliases":{"zh":["产权","交易成本","制度","契约","为什么需要法治"],"en":["property rights","transaction costs","institutions","contracts","rule of law"]}},
"ai-cheap-thinking":{"description":{"zh":"每次技术革命都是某样东西突然变便宜，这次是一部分思考。模型：AI 把能做的任务加速一百万倍，只要做不了的还占四成，整体也只快两倍半；这就是鲍莫尔成本病。","en":"Every technological revolution is something suddenly becoming cheap; this time it is part of thinking. Model: speed up the tasks AI can do a millionfold, and if 40% remain, the whole is only 2.5× faster; this is Baumol's cost disease."},"source":"../demos/scarcity-moves/#c11","lessons":[{"slug":"scarcity-moves","step":null,"anchor":"c11","category":"demos","stage":"university","primary":true}],"aliases":{"zh":["鲍莫尔成本病","瓶颈","AI 对经济的影响","技术革命","为什么教育医疗越来越贵"],"en":["baumol's cost disease","bottleneck","economic impact of AI","technological revolution","why do education and healthcare get more expensive"]}},
"ai-tasks-wages":{"description":{"zh":"一个职业是一捆任务，AI 替代的是任务不是职业；工资取决于你做的事里还有多少是稀缺的。模型：算力增长时，工资先不变、再随互补上涨、最后被替代压住。","en":"An occupation is a bundle of tasks; AI replaces tasks, not occupations, and your wage depends on how much of what you do is still scarce. Model: as compute grows, wages first hold, then rise as complements, then are capped by substitution."},"source":"../demos/scarcity-moves/#c12","lessons":[{"slug":"scarcity-moves","step":null,"anchor":"c12","category":"demos","stage":"university","primary":true}],"aliases":{"zh":["AI 会抢走工作吗","自动化与就业","劳动力市场","AI 和工资","人工智能会不会让人失业","互补还是替代"],"en":["will AI take my job","automation and jobs","labor market","labour market","AI and wages","complement or substitute"]}},
"relative-prices-after-ai":{"description":{"zh":"认知变便宜之后，收入会流向仍然稀缺的东西。作者对相对价格方向的判断：方向较有把握，长短只是示意。","en":"Once thinking gets cheap, income flows toward whatever stays scarce. The author's judgement of which relative prices move which way: fairly sure of the direction, the lengths are only illustrative."},"source":"../demos/scarcity-moves/#c13","lessons":[{"slug":"scarcity-moves","step":null,"anchor":"c13","category":"demos","stage":"university","primary":true}],"aliases":{"zh":["AI 之后什么会变贵","相对价格","什么会变便宜"],"en":["what gets more expensive after AI","relative prices","what will get cheaper"]}},
"ai-forecast":{"description":{"zh":"技术决定饼能做多大，饼怎么分由所有权和制度决定。作者逐条标出把握的预测，以及两个最大的不确定：多快，归谁。","en":"Technology decides how big the pie can get; ownership and institutions decide how it is divided. The author's forecasts, each marked with a confidence level, and the two biggest uncertainties: how fast, and who gets it."},"source":"../demos/scarcity-moves/#c14","lessons":[{"slug":"scarcity-moves","step":null,"anchor":"c14","category":"demos","stage":"university","primary":true}],"aliases":{"zh":["AI 的未来","AI 之后会怎样","AI 收益归谁"],"en":["what happens after AI","who benefits from AI"]}}
}});
